#include <bits/stdc++.h>
using namespace std;

int main() {
    int n;
    cin >> n;
    vector<int> a(n);
    long long ans1 = 0, ans2 = 0;
    for (int i = 0; i < n; i++) {
        cin >> a[i];
    }
    for (int i = 0; i < n; i++) {
        int t;
        cin >> t;
        if (a[i] > t) {
            ans1 += a[i] - t;
        } else {
            ans2 += t - a[i];
        }

    }
    cout << max(ans1, ans2) << endl;
    return 0;
}

